"""Generates lib/ui/theme/adventure_tokens.dart from replica/design/tokens.json.

Run from the project root after any token change:
    python3 tool/gen_tokens.py
Components use these names; never raw hex in widgets.
"""
import json
import pathlib
import re

root = pathlib.Path(__file__).resolve().parent.parent
tokens = json.loads((root / "replica/design/tokens.json").read_text())


def camel(name):
    head, *rest = re.split(r"[-_]", name)
    return head + "".join(p[:1].upper() + p[1:] for p in rest)


lines = [
    "// GENERATED by tool/gen_tokens.py from replica/design/tokens.json.",
    "// Do not edit by hand: change the tokens and regenerate.",
    "import 'package:flutter/painting.dart';",
    "",
    "/// RepRaid adventure design tokens (roles; values are RepRaid's own).",
    "class AdvTokens {",
    "  AdvTokens._();",
    "",
]
for name, value in tokens["color"].items():
    lines.append(f"  static const Color {camel(name)} = Color(0xFF{value.lstrip('#').upper()});")
lines.append("")
for name, value in tokens["radius"].items():
    lines.append(f"  static const double radius{name[:1].upper() + camel(name)[1:]} = {float(value)};")
for name, value in tokens["stroke"].items():
    lines.append(f"  static const double stroke{name[:1].upper() + camel(name)[1:]} = {float(value)};")
for name, value in tokens.get("size", {}).items():
    lines.append(f"  static const double size{name[:1].upper() + camel(name)[1:]} = {float(value)};")
lines.append("  static const List<double> space = [" + ", ".join(f"{float(v)}" for v in tokens["space"]) + "];")
lines.append("")
lines.append("  static const String displayFont = 'LilitaOne';")
lines.append("  static const String bodyFont = 'Nunito';")
lines.append("  // Arabic glyphs come from these when the language is Arabic.")
lines.append("  static const List<String> displayFallback = ['Lalezar'];")
lines.append("  static const List<String> bodyFallback = ['Tajawal'];")
for name, t in tokens["type"].items():
    fam = "displayFont" if t.get("family") == "display" else "bodyFont"
    w = t["weight"]
    fb = "displayFallback" if fam == "displayFont" else "bodyFallback"
    lines.append(f"  static const TextStyle {camel(name)} = TextStyle(fontFamily: {fam}, fontFamilyFallback: {fb}, fontSize: {float(t['size'])}, "
                 f"height: {t['line'] / t['size']:.3f}, fontWeight: FontWeight.w{w});")
for name, ms in tokens["motion"].items():
    m = re.match(r"(\d+)ms", ms)
    if m:
        lines.append(f"  static const Duration {camel(name)} = Duration(milliseconds: {m.group(1)});")
lines.append("}")
out = root / "lib/ui/theme/adventure_tokens.dart"
out.write_text("\n".join(lines) + "\n")
print("wrote", out.relative_to(root), len(tokens["color"]), "colours")
